/* =========================================================
 COMPLETE DECISION SYSTEM - Lesson 4 Capstone
 Uses: if/else, switch, ternary, truthy/falsy, &&, ||, early return
========================================================= */

const TOTAL_LESSONS = 10;
let completed = 2;
let xp = 120;
let coins = 30;
let user = { uid: "user123", isLoggedIn: true };
let referrer = "https://code-academy.com/menu.html";
let origin = "https://code-academy.com";

// Decision 1: Auth with early return - like onAuthStateChanged
function checkAuth() {
 if (!user) { // Falsy check - null, undefined, false
 console.log("❌ Decision 1: No user - redirect to login.html");
 return false;
 }
 if (!user.isLoggedIn) {
 console.log("❌ Decision 1: User not logged in");
 return false;
 }
 console.log("✅ Decision 1: User authenticated");
 return true;
}

// Decision 2: Status with correct order - like createLessonCard
function getStatus(lessonId) {
 if (lessonId <= completed) { // Check completed first
 return "completed";
 } else if (lessonId === completed + 1) { // Then current
 return "current";
 } else { // Else locked
 return "locked";
 }
}

// Decision 3: Badge with switch
function getBadge(status) {
 switch (status) {
 case "completed":
 return { text: "Completed", color: "#4ade80", icon: "✅" };
 case "current":
 return { text: "Current", color: "#f7df1e", icon: "▶" };
 case "locked":
 return { text: "Locked", color: "#94a3b8", icon: "🔒" };
 default:
 return { text: "Unknown", color: "#94a3b8", icon: "❓" };
 }
}

// Decision 4: Button with if/else
function getButton(status) {
 if (status === "locked") {
 return { text: "Locked", disabled: true, action: null };
 } else if (status === "completed") {
 return { text: "Review", disabled: false, action: "review" };
 } else {
 return { text: "Start Lesson", disabled: false, action: "start" };
 }
}

// Decision 5: XP level with if/else if ladder
function getXPLevel(xp) {
 if (xp >= 1000) {
 return "Master";
 } else if (xp >= 500) {
 return "Advanced";
 } else if (xp >= 100) {
 return "Intermediate";
 } else if (xp >= 0) {
 return "Beginner";
 } else {
 return "Invalid XP";
 }
}

// Decision 6: Back button with && short-circuit
function handleBack() {
 if (referrer && referrer.includes(origin)) {
 console.log(`Decision 6: Referrer ${referrer} includes ${origin} - history.back()`);
 return "back";
 } else {
 console.log("Decision 6: No valid referrer - go to menu.html");
 return "menu";
 }
}

// Decision 7: Can start with nested and &&
function canStart(lessonId) {
 if (!user ||!user.isLoggedIn) {
 return false;
 }
 if (lessonId > completed + 1) {
 return false;
 }
 // Using && for multiple checks
 if (user.isLoggedIn && xp >= 0 && coins >= 0) {
 return true;
 }
 return false;
}

// Run full simulation
console.log("=== CODE ACADEMY DECISION SYSTEM ===");
checkAuth();
console.log(`\nCompleted: ${completed}, XP: ${xp}, Level: ${getXPLevel(xp)}`);

for (let i = 1; i <= 5; i++) {
 let status = getStatus(i);
 let badge = getBadge(status);
 let button = getButton(status);
 let accessible = canStart(i)? "✅" : "❌";

 // Ternary for display
 let display = status === "completed"? `${badge.icon} ${i}: ${badge.text} - ${button.text}` :
 status === "current"? `${badge.icon} ${i}: ${badge.text} - ${button.text} ${accessible}` :
 `${badge.icon} ${i}: ${badge.text} - ${button.text} ${accessible}`;

 console.log(display);
}

console.log("\n--- Back Button ---");
handleBack();

console.log("\n--- Testing Edge Cases ---");
console.log("Lesson 3 with completed 2:", getStatus(3), canStart(3)? "can start" : "cannot");
console.log("Lesson 5 with completed 2:", getStatus(5), canStart(5)? "can start" : "cannot");
console.log("XP 0 level:", getXPLevel(0)); // Beginner - 0 valid
console.log("XP 120 level:", getXPLevel(120)); // Intermediate

// Truthy/falsy test for XP 0
let zeroXP = 0;
if (zeroXP) {
 console.log("Bug: if (0) false - 0 XP not shown");
} else {
 console.log("Bug: 0 XP falsy - would show No XP, but 0 XP valid! Use explicit check");
}
if (zeroXP!== null && zeroXP!== undefined) {
 console.log(`Fixed: 0 XP is valid - show ${zeroXP} XP`);
}
